  }).filter(a=>a.id);
  fs.writeFileSync(`${path}/created-agents.json`, JSON.stringify(targets, null, 2));
  for (const a of targets) {
    await save(`11-start-agent-${a.i}`, await fetch(`${base}/api/orgs/${org}/agents/${a.id}/start`, {method:'"'POST', headers:H, body:'{}'}));
